    internal PetActionInput(Form parent,Action<bool> action,Action<int> scroll){Owner=parent;this.action=action;this.scroll=scroll;Text="Aion 2 Helper - Pet actions";FormBorderStyle=FormBorderStyle.None;AutoScaleMode=AutoScaleMode.None;StartPosition=FormStartPosition.Manual;ShowInTaskbar=false;TopMost=true;Cursor=Cursors.Hand;}
    internal void Sync(Rectangle rect,bool show,bool explanations=false,string uiLanguage="en"){help=explanations;language=uiLanguage;if(tip.Active!=help)tip.Active=help;if(!show){tip.Hide(this);if(Visible)Hide();return;}Bounds=rect;bool changed=uploaded!=rect.Size;if(changed){using(var b=new Bitmap(Width,Height,PixelFormat.Format32bppPArgb)){using(var g=Graphics.FromImage(b))g.Clear(Color.FromArgb(1,0,0,0));image.Upload(b);}uploaded=rect.Size;}if(changed||!Visible||presented!=rect.Location){image.Present(Handle,Left,Top,255);presented=rect.Location;}if(!Visible){Show();OverlayNative.RaiseWithoutFocus(Handle);}}
