internal sealed class PetToast {
    internal int Id,Amount;internal double Start,Expires,FadeFrom;
    internal double Opacity(double now){return Math.Max(0,Math.Min(1,Math.Min(FadeFrom+(1-FadeFrom)*Math.Max(0,now-Start)/.16,(Expires-now)/.22)));}
    internal static void Add(List<PetToast> notices,int id,int amount,double now,double seconds){var existing=notices.Find(t=>t.Id==id&&t.Expires>now);double opacity=existing==null?0:existing.Opacity(now);if(existing!=null)notices.Remove(existing);notices.Insert(0,new PetToast{Id=id,Amount=amount+(existing==null?0:existing.Amount),Start=now,Expires=now+seconds,FadeFrom=opacity});while(notices.Count>32)notices.RemoveAt(notices.Count-1);}
}
