    internal void OpenAtlas(int id=0){if(!Assets.Ready)return;if(atlas==null){atlas=new PetAtlasWindow(owner,this);atlas.Closed+=delegate{atlas=null;};}atlas.FocusPet(id);if(!atlas.IsVisible)atlas.Show();if(atlas.WindowState==System.Windows.WindowState.Minimized)atlas.WindowState=System.Windows.WindowState.Normal;atlas.Activate();}
    internal void SaveAtlas(Rectangle bounds,int world){owner.SavePetAtlas(bounds,world);}
    internal object Status {get{return new{enabled=options.Enabled,assetError=Assets.Error,quality=Snapshot.Quality,character=Snapshot.Name,server=Snapshot.Server,exact=Snapshot.Exact,known=Snapshot.Totals.Count,completed=Snapshot.Totals.Count(p=>p.Value>=105),pinned=Snapshot.Pins.Length,window=overlay.Status};}}
    internal Bitmap Preview(PetOptions o,string language,double total=68){using(var paint=new PetCardPainter())return paint.Render(Assets,o,language,1038,PetProgress.From((long)total),false,1,true);}
    public void Dispose(){if(disposed)return;disposed=true;if(atlas!=null)atlas.Close();overlay.Dispose();Signal.Save(0,true);Assets.Dispose();}
}
